import envparse

assert envparse.parse_env("A=1\nB = 2 \n") == {"A": "1", "B": "2"}
assert envparse.parse_env("# c\n\n   \nA=1") == {"A": "1"}
assert envparse.parse_env('A="x\\ny"') == {"A": "x\ny"}
assert envparse.parse_env("A='x\\ny'") == {"A": "x\\ny"}
assert envparse.parse_env("A=hello  # trailing") == {"A": "hello"}
assert envparse.parse_env("A=a#b") == {"A": "a#b"}
assert envparse.parse_env("export FOO=bar") == {"FOO": "bar"}
assert envparse.parse_env("A=1\nA=2") == {"A": "2"}
assert envparse.parse_env("A=") == {"A": ""}
assert envparse.parse_env('A="  padded  "') == {"A": "  padded  "}
assert envparse.parse_env("URL=https://x/y?a=b") == {"URL": "https://x/y?a=b"}
for text, message in [("A=1\nnope\n", "invalid line 2: nope"), ("1BAD=x", "invalid line 1: 1BAD=x"), ("=x", "invalid line 1: =x")]:
    try:
        envparse.parse_env(text)
    except ValueError as error:
        assert str(error) == message
    else:
        raise AssertionError(text)
assert envparse.parse_env('A="\\n\\t\\r\\\"\\\\\\q"') == {"A": '\n\t\r"\\\\q'}
assert envparse.parse_env("A=one\t # comment") == {"A": "one"}
assert envparse.parse_env("A=one#two\nB=3\r\n") == {"A": "one#two", "B": "3"}
assert [name for name in vars(envparse) if not name.startswith("_")] == ["parse_env"]
assert envparse.parse_env("export\tFOO=bar") == {"export\tFOO": "bar"}
print("all checks passed")
